mapper.select:
SELECT * FROM interview_report_task
WHERE task_state = 'QUEUED' AND delivery_state = 'PENDING' AND next_send_at <= UTC_TIMESTAMP(6)
ORDER BY next_send_at, id LIMIT #{limit}

SELECT * FROM interview_report_task
WHERE task_state = 'QUEUED' AND delivery_state = 'LEASED' AND dispatch_lease_until <= UTC_TIMESTAMP(6)
ORDER BY dispatch_lease_until, id LIMIT #{limit}

mapper.update:
UPDATE interview_report_task SET delivery_state = 'PENDING', dispatch_token = NULL, dispatch_lease_until = NULL,
    next_send_at = TIMESTAMPADD(SECOND, #{backoffSeconds}, UTC_TIMESTAMP(6))
WHERE id = #{id} AND task_state = 'QUEUED' AND delivery_state = 'LEASED' AND dispatch_token = #{token}

UPDATE interview_report_task SET task_state = 'SUCCEEDED'
WHERE id = #{id} AND task_state = 'RUNNING' AND execution_version = #{executionVersion}
    AND execution_deadline > UTC_TIMESTAMP(6)
